// Lee ?slug= y ?dias= del querystring, con valores por defecto.
const q = $input.first().json.query || {};
const slug = (q.slug || 'tumbao').toString().slice(0, 60);
let dias = parseInt(q.dias, 10);
if (!Number.isFinite(dias) || dias < 1 || dias > 60) dias = 14;
return [{ json: { slug, dias } }];

// Agrupa las sesiones por día en hora de Bogotá para que la página
// no tenga que hacer aritmética de zonas horarias en el navegador.
const filas = $input.all().map(i => i.json).filter(r => r && r.sesion_id);
const tz = (filas[0] && filas[0].timezone) || 'America/Bogota';

const fFecha = new Intl.DateTimeFormat('es-CO', {
  timeZone: tz, weekday: 'long', day: 'numeric', month: 'long'
});
const fHora = new Intl.DateTimeFormat('es-CO', {
  timeZone: tz, hour: 'numeric', minute: '2-digit', hour12: true
});
const fClave = new Intl.DateTimeFormat('en-CA', {
  timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit'
});

// es-CO devuelve "7:00 p. m."; en la tarjeta cabe mejor "7:00 pm".
const compacta = s => s
  .replace(/\u202f|\u00a0/g, ' ')
  .replace(/\s*a\.\s*m\./i, ' am')
  .replace(/\s*p\.\s*m\./i, ' pm');

const dias = new Map();
for (const r of filas) {
  const d = new Date(r.start_at);
  const clave = fClave.format(d);
  if (!dias.has(clave)) {
    dias.set(clave, { fecha: clave, etiqueta: fFecha.format(d), sesiones: [] });
  }
  dias.get(clave).sesiones.push({
    sesion_id: r.sesion_id,
    clase: r.clase,
    estilo: r.estilo,
    nivel: r.nivel,
    instructor: r.instructor,
    hora: compacta(fHora.format(d)),
    start_at: r.start_at,
    cupo_total: r.cupo_total,
    cupos_disponibles: r.cupos_disponibles,
    agotada: r.cupos_disponibles <= 0
  });
}

return [{ json: { ok: true, timezone: tz, dias: [...dias.values()] } }];
